save(59,dict(paragraphs=["Nurul Hoque is a Bangladeshi poet, novelist and editor whose work appears in Bengali and English. His editorial work includes the Dhaka periodical Amader Buriganga and Odyssey International Anthology of World Poets 2020. In his essay ‘My Poetic Thoughts’, he describes poetry as an inward conversation in which human feeling and the natural world meet.","That connection is visible in the poems gathered here. ‘Life Need Compassion’ moves from suffering towards a shared call for kindness, likening compassion to sunlight. ‘You Will Come Again’ places longing on the dry bank of the Kaliganga, where heat, sand and the season of Chaitra make an awaited return feel like relief from drought."],sources=[source('Poémame — Nurul Hoque poems and biography','https://revista.poemame.com/2019/02/20/3-poemas-de-nurul-hoque-poeta-bengali/',['Bengali poet and Amader Buriganga editor in Dhaka']),source('INNSÆI — My Poetic Thoughts, January–March 2023','https://www.innsaeijournal.com/wp-content/uploads/2023/10/INNSAEI-Journal-Jan-March-23-Issue-Final.pdf',['Author essay on poetry as soliloquy and relation to nature','Bangladeshi bilingual poet, novelist and editor identification'],access='search_index_excerpt'),source('INNSÆI — January–March 2025 contributor biography','https://www.innsaeijournal.com/wp-content/uploads/2025/05/INNSAEI-Vol-VI-Issue-1-Jan-Mar-25.pdf',['Odyssey International Anthology of World Poets 2020 editor'],access='search_index_excerpt'),source('ThriftBooks — Odyssey anthology catalogue and editor’s note','https://www.thriftbooks.com/w/odyssey-international-anthology-of-world-poets-2020/29696430/',['Anthology ISBN 9798723992313','Editorial note signed Nurul Hoque'],access='search_index_excerpt')],books=[dict(title='Odyssey International Anthology of World Poets 2020',detail='International poetry anthology edited by Nurul Hoque. Catalogue ISBN 9798723992313.',url='https://www.thriftbooks.com/w/odyssey-international-anthology-of-world-poets-2020/29696430/')],identity_match='Distinctive Amader Buriganga and Odyssey editorial affiliations match captured biography, journal contributor/essay notes, author member profile and anthology editorial note. Not merged with namesake politicians or other poets.',poems_read=[dict(id=332,title='You Will Come Again',basis='Full reconciled English source read: Kaliganga, Beutha shore, Chaitra heat and awaited arrival; existing reconciliation preserved.'),dict(id=82,title='Life Need Compassion',basis='Full captured English poem read; suffering, tears, compassion and sunlight.')],limitations=['Named honours and international foundation offices are self-reported across bios; not expanded or treated as state/national honours.','No current book total, birth date or present executive appointment asserted.','INNSAEI 2025 PDF and retail direct fetches failed; indexed evidence distinguished from opened Poémame page.','Anthology 2020 title versus March 2021 retail date preserved without guessing release chronology.','Poetry Nation member profile is self-published evidence, not independent verification.'],research_leads=[dict(url='https://www.poetrynation.com/members/193862/',access='opened_page',finding='Self-published profile matches distinctive affiliations and lists Bengali/English books; used for identity cross-check only.'),dict(url='https://www.kobo.com/sg/en/ebook/uGy3H5F8ED6na9oPEAESFQ',access='search_index_excerpt',finding='Urdu Pain of Innocence listing credits translator Naila Hina; no unsupported English-edition book card created.')],next_action='Independent author/editor review; fuller publisher bibliography and award provenance if desired.'))
